const body = $input.first().json.body || $input.first().json;
const project_id = body.project_id || '';
if (!project_id) throw new Error('project_id is required');
const ad_account_id = body.ad_account_id || 'act_921159353090591';
const days = Math.min(Math.max(parseInt(body.days) || 30, 1), 90);
const limit = Math.min(Math.max(parseInt(body.limit) || 5, 1), 10);

const now = new Date();
const since = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
const sinceStr = since.toISOString().split('T')[0];
const untilStr = now.toISOString().split('T')[0];

return [{ json: { project_id, ad_account_id, days, limit, since: sinceStr, until: untilStr } }];

const resp = $input.first().json;
const data = resp.data || [];
if (!data.length) return [{ json: { _empty: true } }];

return data.map(ad => {
  const actions = ad.actions || [];
  const actionValues = ad.action_values || [];
  const purchases = actions.find(a => a.action_type === 'purchase') || {};
  const revenue = actionValues.find(a => a.action_type === 'purchase') || {};
  const spend = parseFloat(ad.spend || 0);
  const rev = parseFloat(revenue.value || 0);
  return {
    json: {
      ad_id: ad.ad_id,
      ad_name: ad.ad_name,
      spend: spend.toFixed(2),
      impressions: ad.impressions || '0',
      clicks: ad.clicks || '0',
      ctr: parseFloat(ad.ctr || 0).toFixed(2),
      cpc: parseFloat(ad.cpc || 0).toFixed(2),
      cpm: parseFloat(ad.cpm || 0).toFixed(2),
      purchases: purchases.value || '0',
      revenue: rev.toFixed(2),
      roas: spend > 0 ? (rev / spend).toFixed(2) : '0.00'
    }
  };
});

const items = $input.all();
const metrics = $('Parse Ads + Metrics').all();
return items.map((item, i) => {
  const ad = item.json;
  const adId = ad.id || ad.ad_id;
  const m = metrics.find(m => m.json.ad_id === adId)?.json || {};
  const creative = ad.creative || {};
  const spec = creative.object_story_spec || {};
  let creativeType = 'image';
  if (creative.video_id || spec.video_data) creativeType = 'video';
  const videoId = creative.video_id || (spec.video_data ? spec.video_data.video_id : '') || '';
  const thumbnailUrl = creative.thumbnail_url || (spec.link_data ? spec.link_data.picture : '') || '';
  const adCopy = creative.body || (spec.link_data ? spec.link_data.message : '') || '';
  const headline = creative.title || (spec.link_data ? spec.link_data.name : '') || '';
  const ctaType = creative.call_to_action_type || (spec.link_data && spec.link_data.call_to_action ? spec.link_data.call_to_action.type : '') || '';
  return { json: { ...m, creative_type: creativeType, video_id: videoId, image_url: thumbnailUrl, ad_copy: adCopy, headline, cta_type: ctaType } };
});

// Video source unavailable, fallback to thumbnail analysis
const adData = $('Extract Creative Data').first().json;
return [{ json: { image_url: adData.image_url || adData.thumbnail_url || '' } }];

function extractText(obj) {
  if (!obj) return "";
  // REST API format: { candidates: [{ content: { parts: [{ text: "..." }] } }] }
  if (obj.candidates && obj.candidates[0]?.content?.parts?.[0]?.text) {
    return obj.candidates[0].content.parts[0].text;
  }
  // LangChain node format
  if (obj.content?.parts?.[0]?.text) return obj.content.parts[0].text;
  if (typeof obj === "string") return obj;
  if (obj.text) return obj.text;
  if (obj.output) return obj.output;
  return "";
}

function extractJSON(text) {
  if (!text || typeof text !== "string") return null;
  try { return JSON.parse(text); } catch(e) {}
  const codeBlock = text.match(/```json([\s\S]*?)```/);
  if (codeBlock) { try { return JSON.parse(codeBlock[1].trim()); } catch(e) {} }
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first !== -1 && last !== -1) {
    try { return JSON.parse(text.slice(first, last + 1)); } catch(e) {}
  }
  return null;
}

const items = $input.all();
return items.map(item => {
  const rawText = extractText(item.json);
  const parsed = extractJSON(rawText);
  if (parsed) {
    return { json: { ...item.json, gemini: parsed } };
  }
  // If we got an error response from Gemini
  const error = item.json.error;
  const errorMsg = error ? (typeof error === 'string' ? error : (error.message || JSON.stringify(error))) : 'Could not parse Gemini response';
  return { json: { ...item.json, gemini: { error: errorMsg } } };
});

const adData = $('Extract Creative Data').first().json;
const project_id = $('Extract Params').first().json.project_id;
const gemini = $json.gemini || {};
// Use gemini.kind (from actual analysis) not adData.creative_type (from ad metadata)
const isVideo = gemini.kind === 'video';

const hookText = gemini.hook_text || adData.headline || '';

// Clean markdown from why_it_works
function cleanMd(s) { return (s || '').replace(/\*\*/g, '').replace(/\*/g, '').trim(); }

const whyItWorks = Array.isArray(gemini.why_it_works)
  ? gemini.why_it_works.map(cleanMd).join('; ')
  : cleanMd(gemini.why_it_works || '');

const scores = gemini.scores || {};
const scoreVals = Object.values(scores).map(v => parseFloat(v) || 0);
const avgScore = scoreVals.length > 0 ? (scoreVals.reduce((a,b) => a+b, 0) / scoreVals.length).toFixed(1) : 'N/A';
const scoreStr = Object.entries(scores).map(([k,v]) => k + ': ' + v).join(', ');

const takeaways = Array.isArray(gemini.key_takeaways_for_writer)
  ? gemini.key_takeaways_for_writer.map(cleanMd).join('; ')
  : cleanMd(gemini.key_takeaways_for_writer || '');

let adCopy = adData.ad_copy || '';
if (isVideo && gemini.transcript) {
  adCopy = gemini.transcript;
}

let notes = '';
if (isVideo) {
  const keyPhrases = Array.isArray(gemini.key_phrases) ? gemini.key_phrases.join(', ') : '';
  const editNotes = cleanMd(gemini.editing_notes || '');
  notes = 'KEY PHRASES: ' + keyPhrases + ' | EDITING: ' + editNotes + ' | TAKEAWAYS: ' + takeaways;
} else {
  // Image analysis
  const onImageText = Array.isArray(gemini.on_image_text) ? gemini.on_image_text.join(', ') : '';
  const assessment = cleanMd(gemini.ad_copy_assessment || '');
  notes = 'Scores: ' + scoreStr + ' (avg ' + avgScore + ') | TEXT: ' + onImageText + ' | ASSESSMENT: ' + assessment + ' | TAKEAWAYS: ' + takeaways;
}

return [{ json: {
  project_id: project_id,
  ad_name: adData.ad_name,
  hook_text: cleanMd(hookText),
  ad_copy: adCopy,
  why_it_works: whyItWorks,
  metrics_text: 'CTR ' + (parseFloat(adData.ctr) || 0).toFixed(2) + '%, CPC $' + (parseFloat(adData.cpc) || 0).toFixed(2) + ', ROAS ' + (parseFloat(adData.roas) || 0).toFixed(1) + 'x, Spend $' + (parseFloat(adData.spend) || 0).toFixed(0),
  notes: notes,
  uploaded_by: 'Ad Analysis Bot'
} }];

const params = $('Extract Params').first().json;
const adCount = $('Parse Ads + Metrics').all().filter(a => !a.json._empty).length;
return [{ json: { status: 'success', ads_analyzed: adCount, message: adCount + ' ads analyzed and stored in Reference_Ads for project ' + params.project_id } }];

