let base64Data, mimeType;
try {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  base64Data = buffer.toString('base64');
  mimeType = $input.first().binary[binaryKey]?.mimeType || 'video/mp4';
} catch(e) {
  return [{ json: { requestBody: { contents: [{ parts: [{ text: "Video binary data not available: " + e.message }] }] } } }];
}

const prompt = "You are an expert UGC ad analyst. Analyze this video ad for a UGC script writer.

Analyze with extreme detail:

1. OPENING HOOK (first 3 seconds): What visual and audio elements grab attention? What exact words are spoken first?
2. FULL TRANSCRIPT: Transcribe all spoken words with approximate timestamps
3. SCRIPT STRUCTURE: Break down into sections (Hook -> Problem -> Solution -> Proof -> CTA) with timestamps
4. VISUAL ELEMENTS: Camera angles, text overlays, product shots, B-roll, scene transitions
5. AUDIO: Music, sound effects, speaking tone, energy level, pacing
6. KEY PHRASES: Most persuasive words/phrases and why they work
7. EDITING: Cut frequency, transitions, pacing rhythm
8. WHY IT WORKS: 5 specific reasons this video ad converts
9. SCORES (0-10): hook_strength, script_structure, visual_quality, audio_impact, authenticity, overall
10. KEY TAKEAWAYS: Actionable insights for a UGC script writer to replicate this ad's success

Return ONLY valid JSON (no markdown) with this schema:
{"kind":"video","hook_text":"opening hook words","transcript":"full transcript","script_breakdown":[{"section":"Hook","timestamp":"0:00-0:03","text":"...","purpose":"..."}],"visual_elements":["element1","element2"],"audio_analysis":{"music":"...","tone":"...","pacing":"..."},"key_phrases":["phrase1","phrase2"],"editing_notes":"...","why_it_works":["reason1","reason2"],"scores":{"hook_strength":0,"script_structure":0,"visual_quality":0,"audio_impact":0,"authenticity":0,"overall":0},"key_takeaways_for_writer":["takeaway1","takeaway2"],"tone":"...","cta_text":"..."}";
